function validate([a, b, c]) {
  for (const [name, value] of [['a', a], ['b', b], ['c', c]]) {
    if (!Number.isInteger(value) || value < 1 || value > 1e9) return `${name} must be an integer from 1 to 10^9.`;
  }
  return null;
}

