function minFlips(a, b, c) {
  const width = 31;
  const sa = a.toString(2).padStart(width, '0');
  const sb = b.toString(2).padStart(width, '0');
  const sc = c.toString(2).padStart(width, '0');
  let total = 0;
  for (let p = 0; p < width; p++) {
    let cheapest = Infinity;
    for (const x of ['0', '1'])
      for (const y of ['0', '1']) {
        const or = x === '1' || y === '1' ? '1' : '0';
        if (or !== sc[p]) continue;
        cheapest = Math.min(cheapest, (x !== sa[p] ? 1 : 0) + (y !== sb[p] ? 1 : 0));
      }
    total += cheapest;
  }
  return total;
}

