function generate(rand, size) {
  const pick = () => {
    if (size === 'large') return 1 + Math.floor(rand() * 1e9);
    const r = rand();
    if (r < 0.6) return 1 + Math.floor(rand() * 15);
    if (r < 0.8) return 1 + Math.floor(rand() * 1000);
    return 1 + Math.floor(rand() * 1e9);
  };
  return [pick(), pick(), pick()];
}
